bool mark_started(std::size_t slot) noexcept {
    if (slot >= N) return false;
    std::size_t write = 0;
    for (std::size_t read = 0; read < N; ++read) {
        if (order_[read] != slot) order_[write++] = order_[read];
    }
    order_[N - 1] = slot;
    return true;
}

std::optional<std::size_t> start(std::size_t owner,
                                 const Pcm16& clip) noexcept {
    if (owner == kNoOwner) return std::nullopt;

    std::size_t slot = kMaxVoices;
    for (std::size_t i = 0; i < kMaxVoices; ++i) {
        if (!mixer_.playing(i)) {
            slot = i;
            break;
        }
    }
    if (slot == kMaxVoices) slot = order_.oldest();

    if (!mixer_.start(slot, clip)) return std::nullopt;

    owners_[slot] = owner;
    order_.mark_started(slot);
    return slot;
}

void stop_owner(std::size_t owner) noexcept {
    if (owner == kNoOwner) return;
    for (std::size_t i = 0; i < kMaxVoices; ++i) {
        if (owners_[i] == owner) {
            mixer_.stop(i);
            owners_[i] = kNoOwner;
        }
    }
}

void Player::unload(std::size_t slot) noexcept {
    if (dev_ == 0) return;
    if (slot >= kSlots) return;
    // No global pause: the other slots must keep playing while this one is
    // retired. Every voice borrowing the target clip is detached.

    // Retired outside the lock scope: the old PCM buffer is destroyed only
    // after DeviceLock runs SDL_UnlockAudioDevice.
    std::optional<Pcm16> retired;
    {
        DeviceLock lock(dev_);
        pool_.stop_owner(slot);
        retired.swap(clips_[slot]);
    }
    // `retired` destructs here, i.e. the old PCM deallocation happens post-unlock.
}

std::size_t cursor_frames(std::size_t owner) const noexcept {
    if (owner == kNoOwner) return 0;
    const std::array<std::size_t, kMaxVoices>& ordered = order_.ordered();
    for (std::size_t k = kMaxVoices; k > 0; --k) {
        const std::size_t slot = ordered[k - 1];
        if (owners_[slot] == owner) return mixer_.cursor_frames(slot);
    }
    return 0;
}

