{
    slot = static_cast<int>(s_sfxOrder.oldest());
    // Stop/Flush may still be pending on the audio thread. End the old
    // borrow before overwriting the only handle that tracks its PCM.
    s_sfxVoices[slot]->DestroyVoice();
    s_sfxVoices[slot] = nullptr;
    s_sfxFormats[slot] = {};
    s_sfxHandles[slot] = 0;
}

bool Player::play(std::size_t slot) noexcept {
    // Closed takes priority over an out-of-range slot.
    if (dev_ == 0) return false;
    if (slot >= kSlots) return false;
    if (!clips_[slot].has_value()) return false;

    bool started = false;
    {
        DeviceLock lock(dev_);
        started = pool_.start(slot, *clips_[slot]).has_value();
    }
    // Unpause only after the lock is released.
    SDL_PauseAudioDevice(dev_, 0);
    return started;
}
